-- VetMate | 06_booking.sql
-- Chạy sau 01_create_schemas.sql, 02_auth.sql, 03_seed_auth.sql,
-- 04_medical_pet.sql, 05_seed_medical_catalog.sql.
-- PostgreSQL: các định danh camelCase phải đặt trong dấu ngoặc kép.
-- Chưa ràng buộc FK sang clinic vì chưa có DDL clinic chính thức.
-- Không chạy trên production trước khi kiểm tra/migrate dữ liệu.

BEGIN;
CREATE SCHEMA IF NOT EXISTS booking;

CREATE TABLE IF NOT EXISTS booking."appointments" (
    "appointmentID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "appointmentCode" VARCHAR(30) NOT NULL UNIQUE,
    "petID" BIGINT NOT NULL REFERENCES medical."pets"("petID") ON DELETE RESTRICT,
    "serviceID" BIGINT NOT NULL, -- FK tới clinic.services: bổ sung sau khi chốt DDL clinic
    "veterinarianID" BIGINT, -- FK tới clinic.veterinarians: bổ sung sau khi chốt DDL clinic
    "appointmentType" VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED',
    "priority" VARCHAR(20) NOT NULL DEFAULT 'NORMAL',
    "scheduledDate" DATE NOT NULL,
    "startTime" TIME NOT NULL,
    "endTime" TIME, -- EMERGENCY có thể chưa biết thời gian kết thúc dự kiến
    "reason" TEXT NOT NULL,
    "ownerNote" TEXT,
    "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    "confirmedByStaffID" BIGINT, -- FK clinic.clinicStaff sau khi chốt DDL
    "confirmedAt" TIMESTAMPTZ,
    "cancelledAt" TIMESTAMPTZ,
    "cancelReason" TEXT,
    "checkedInAt" TIMESTAMPTZ,
    "createdByUserID" BIGINT NOT NULL REFERENCES auth."users"("userID") ON DELETE RESTRICT,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "ckAppointmentsType" CHECK ("appointmentType" IN ('SCHEDULED', 'EMERGENCY')),
    CONSTRAINT "ckAppointmentsPriority" CHECK ("priority" IN ('NORMAL', 'URGENT')),
    CONSTRAINT "ckAppointmentsStatus" CHECK ("status" IN
        ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'NO_SHOW')),
    CONSTRAINT "ckAppointmentsTime" CHECK ("endTime" IS NULL OR "endTime" > "startTime"),
    CONSTRAINT "ckAppointmentsScheduledTime" CHECK ("appointmentType" <> 'SCHEDULED' OR "endTime" IS NOT NULL),
    CONSTRAINT "ckAppointmentsEmergencyPriority" CHECK ("appointmentType" <> 'EMERGENCY' OR "priority" = 'URGENT')
);

CREATE TABLE IF NOT EXISTS booking."queueEntries" (
    "queueEntryID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "appointmentID" BIGINT NOT NULL UNIQUE REFERENCES booking."appointments"("appointmentID") ON DELETE RESTRICT,
    "queueDate" DATE NOT NULL, -- Ngày thực tế check-in; số thứ tự reset theo ngày
    "queueNumber" INTEGER NOT NULL,
    "checkedInAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "calledAt" TIMESTAMPTZ,
    "startedAt" TIMESTAMPTZ,
    "completedAt" TIMESTAMPTZ,
    "status" VARCHAR(20) NOT NULL DEFAULT 'WAITING',
    CONSTRAINT "uqQueueEntriesDateNumber" UNIQUE ("queueDate", "queueNumber"),
    CONSTRAINT "ckQueueEntriesNumber" CHECK ("queueNumber" > 0),
    CONSTRAINT "ckQueueEntriesStatus" CHECK ("status" IN ('WAITING', 'CALLED', 'IN_SERVICE', 'DONE', 'CANCELLED'))
);

CREATE INDEX IF NOT EXISTS "idxAppointmentsDateStatus"
    ON booking."appointments" ("scheduledDate", "status");
CREATE INDEX IF NOT EXISTS "idxAppointmentsPetDate"
    ON booking."appointments" ("petID", "scheduledDate");
CREATE INDEX IF NOT EXISTS "idxAppointmentsVetDateTime"
    ON booking."appointments" ("veterinarianID", "scheduledDate", "startTime");
CREATE INDEX IF NOT EXISTS "idxQueueEntriesDateStatus"
    ON booking."queueEntries" ("queueDate", "status");

CREATE OR REPLACE FUNCTION booking."setAppointmentUpdatedAt"()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW."updatedAt" = now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trgAppointmentsUpdatedAt" ON booking."appointments";
CREATE TRIGGER "trgAppointmentsUpdatedAt"
BEFORE UPDATE ON booking."appointments"
FOR EACH ROW EXECUTE FUNCTION booking."setAppointmentUpdatedAt"();

COMMENT ON TABLE booking."appointments" IS 'Lịch đặt trước và lượt cấp cứu tiếp nhận trực tiếp trong giờ hành chính';
COMMENT ON COLUMN booking."appointments"."serviceID" IS 'Sẽ FK tới dịch vụ clinic khi nhóm quản lý hoàn thiện DDL';
COMMENT ON COLUMN booking."appointments"."veterinarianID" IS 'Có thể NULL lúc chờ phân công, cần bác sĩ trước khi bắt đầu khám';
COMMENT ON COLUMN booking."appointments"."appointmentType" IS 'SCHEDULED: đặt lịch; EMERGENCY: tiếp nhận trực tiếp';
COMMENT ON TABLE booking."queueEntries" IS 'Hàng đợi tạo khi lễ tân check-in, bao gồm cả cấp cứu';
COMMIT;

